SET LOCAL statement_timeout='30s';
CREATE FUNCTION pg_temp.fixture_insert(tbl regclass,rowdata jsonb) RETURNS void LANGUAGE plpgsql AS $$
DECLARE cols text; BEGIN SELECT string_agg(quote_ident(a.attname),',' ORDER BY a.attnum) INTO cols FROM pg_attribute a WHERE a.attrelid=tbl AND a.attnum>0 AND NOT a.attisdropped AND a.attgenerated='' AND rowdata ? a.attname;
 EXECUTE format('INSERT INTO %s(%s) OVERRIDING SYSTEM VALUE SELECT %s FROM jsonb_populate_record(NULL::%s,$1)',tbl,cols,cols,tbl) USING rowdata; END $$;
CREATE TEMP TABLE lifecycle_results(name text,result jsonb);
CREATE FUNCTION pg_temp.check_result(name text,result jsonb) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF result->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION '% failed: %',name,result; END IF;IF name IN ('addon_close','addon_replay','launch_addon_close') AND (result->>'finalized')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION '% failed to finalize: %',name,result; END IF;
IF name='entry_still_open' AND (result->>'entry_closed')::boolean IS DISTINCT FROM false THEN RAISE EXCEPTION 'Entry unexpectedly closed: %',result; END IF;
IF name IN ('complete_launch','launch_replay') AND (result->>'completed')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'Launch incomplete: %',result; END IF;
IF name IN ('entry_close','entry_close_replay') AND ((result->>'entry_closed')::boolean IS DISTINCT FROM true OR (result->>'finalization_deferred')::boolean IS DISTINCT FROM true) THEN RAISE EXCEPTION 'Free Buy entry close must defer to its promised add-on: %',result; END IF;
INSERT INTO lifecycle_results VALUES(name,result);END $$;
