CREATE FUNCTION pg_temp.expect_refusal(label text, command text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE refused boolean:=false; code text; msg text; BEGIN
 BEGIN EXECUTE command; EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS code=RETURNED_SQLSTATE,msg=MESSAGE_TEXT;refused:=true; END;
 IF NOT refused THEN RAISE EXCEPTION 'Invalid operation unexpectedly succeeded: %',label; END IF;
 INSERT INTO lifecycle_results VALUES(label,jsonb_build_object('refused',true,'sqlstate',code,'reason',msg)); END $$;
